Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
Ltac accok_fp_on ::= fail.

Section SELSTRK.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.
Hypothesis FKC : rt_fk_contracts RT.
Hypothesis SCR : selCreate2_cps RT.
Hypothesis SSE : selSetElement_cps RT.
Hypothesis ACCTSEL : forall k Σ m, 1 <= k <= 4 -> ART RT Σ m -> acc asegs m (A_TSEL k) 31.
Local Ltac ul := unfold SEGTOP_A, STACK_WIN, USTACK_TOP, RT_STACK in *; lia.

(* [comment removed for export] *)

Ltac shbr_merge_beqz ru FAST OK :=
  lazymatch goal with
  | |- evt ?segs ?Q (MS ?R ?F _ ?fc ?rv ?m ?ro) =>
      eapply (evt_cut segs (fun ms' => exists u' : word,
                 ms' = MS (@bvmap_set 5 word ru u' R) F (Z_to_bv 64 FAST) fc rv m ro));
      [ destruct OK as [OK|[OK ?]];
        [ brT; apply evt_done;
          lazymatch goal with |- exists u', _ = MS (@bvmap_set 5 word ?r u' ?R') _ _ _ _ _ _ =>
            let p := eval vm_compute in (bv_key r) in
            let v := eval cbv beta iota delta [tget mkR] in (tget p R') in
            lazymatch v with Some ?x => exists x end end;
          norm_regset; reflexivity
        | brF; bsteps_to FAST; apply evt_done; eexists; norm_regset; reflexivity ]
      | let u' := fresh "u" in let E := fresh "E" in let ms := fresh "ms" in
        intros ms (u' & E); subst ms; norm_regset; clear OK ]
  end.
(* [comment removed for export] *)
(* [comment removed for export] *)
Ltac shbr_beqz1 :=
  lazymatch goal with
  | |- evt ?segs ?Q (MS ?R ?F (if ?c then Z_to_bv 64 ?FAST else Z_to_bv 64 ?SLOW) ?fc ?rv ?m ?ro) =>
      let b := shbyte_of c in
      lazymatch goal with
      | K : shk m b ?X |- _ =>
          instr_at segs SLOW ltac:(fun i =>
            lazymatch i with
            | OpImm ALU_AND ?ru _ _ =>
                let S4 := eval vm_compute in (SLOW + 4)%Z in
                instr_at segs S4 ltac:(fun i2 =>
                  let szm1 := lazymatch i2 with
                              | OpImm ALU_ADD _ _ ?imm => eval vm_compute in (bv_unsigned imm)
                              | _ => constr:(0%Z) end in
                  let sz := eval vm_compute in (szm1 + 1)%Z in
                  let OK := fresh "SHOK" in
                  first [
                    match goal with
                    | ACC : acc asegs m ?a ?n |- _ =>
                        assert (OK : sh_ok b (X + sz - 1)) by (apply (shk_ok m a n X sz b ACC K); lia)
                    end
                  | fail 1 "shbr_beqz1: cannot prove the access addressable:" X sz ];
                  let BB := fresh "BB" in
                  assert (BB : 0 <= bv_unsigned b < 8)
                    by (pose proof (bv_unsigned_in_range 8 b); destruct OK as [?|[? ?]]; lia);
                  rewrite ?(sxb_small b) by lia;
                  shbr_merge_beqz ru FAST OK; clear K BB)
            end)
      end
  end.
(* [comment removed for export] *)
Ltac tsel_cells txt off :=
  lazymatch goal with MIx : mem_inv asegs ?mm, A : ART RT ?S ?mm, E : txt = A_TSEL _ |- cps _ (ASTA RT ?S _ (eq (MS _ _ _ _ _ ?mm _))) _ =>
    try (lazymatch goal with _ : acc asegs mm txt 31 |- _ => idtac | _ =>
           let AC := fresh "ACCT" in pose proof (ACCTSEL 1 S mm ltac:(clear; lia) A) as AC; rewrite <- E in AC end);
    let TB := fresh "TB" in let TC := fresh "TC" in
    pose proof (tsel_bytes mm 1 MIx ltac:(clear; lia)) as TB; rewrite <- E in TB;
    pose proof (bytes_C1 mm txt _ off _ TB ltac:(reflexivity)) as TC; clear TB;
    let o := eval cbv in (Z.of_nat off) in change (Z.of_nat off) with o in TC; try rewrite Z.add_0_r in TC
  end.
(* [comment removed for export] *)
Ltac sobj_move sel lo :=
  lazymatch goal with |- context [MS _ _ _ _ _ ?mb _] =>
    lazymatch goal with
    | SO : sel_obj _ mb sel _ |- _ => idtac
    | SO : sel_obj ?lv ?ma sel ?svx, MUx : munch ?W ?ma mb, A : ART RT ?S ?mq, SPc : rt_sp0 RT ?S = _, L1 : rt_sp0 RT _ - 8388608 <= lo, L2 : lo + _ <= _ |- _ =>
        let KL := fresh "KL" in
        assert (KL : keeps_live lv ma mb)
          by (apply (keeps_live_of_munch lv W ma mb MUx); intros b kk xx Hin Hx; cbn [outside];
              repeat match goal with E : rt_live RT _ = rt_live RT _ |- _ => rewrite E in Hin end;
              pose proof (af_live_range RT AF S mq b kk A Hin) as (_ & R & _); rewrite SPc in R; unfold STACK_WIN in R;
              clear - R Hx L1 L2; repeat split; try exact I; lia);
        pose proof (sel_obj_keepL _ ma mb sel svx KL SO) as SOBJc; clear SO KL; rename SOBJc into SOBJ
    end end.
(* [comment removed for export] *)
Ltac sobj_origin sel lo cy cx :=
  lazymatch goal with |- context [MS _ _ _ _ _ ?mb _] =>
    lazymatch goal with
    | SO : sel_obj ?lv ?ma sel ?svx, MUx : munch ?W ?ma mb, A : ART RT ?S ?mq, SPc : rt_sp0 RT ?S = _, KINx : In (sel, 32) ?lv,
      L1 : rt_sp0 RT _ - 8388608 <= lo, L2 : lo + _ <= _, KC : rw_cells asegs mb sel _ |- _ =>
        let K := fresh "K" in
        assert (K : forall b k, In (b, k) lv -> b <> sel -> forall a : word, b <= bv_unsigned a < b + k -> mb a = ma a)
          by (intros b kk Hin Hne xx Hx; apply MUx; cbn [outside];
              pose proof (af_live_range RT AF S mq b kk A Hin) as (_ & R & _); rewrite SPc in R; unfold STACK_WIN in R;
              pose proof (live_apart2 RT AF S mq b kk sel 32 A Hin KINx Hne) as R2;
              clear - R R2 Hx L1 L2; repeat split; try exact I; lia);
        pose proof (sel_obj_origin lv ma mb sel svx cy cx SO K KC ltac:(cbn; clear; lia) ltac:(cbn; clear; lia)) as SOBJc;
        cbn [s_sy s_sx s_data s_rowp s_rows] in SOBJc; clear SO K KC; rename SOBJc into SOBJ
    end end.
Ltac selstr_call sel lo :=
  eapply cps_seq;
  [ lazymatch goal with SO : sel_obj _ _ sel ?svx |- _ =>
      eapply SSE with (sv := svx); rt_side idtac;
      lazymatch goal with
      | |- sel_obj _ _ _ _ => first [exact SO | lazymatch goal with |- ?g => idtac "SOBJ-mismatch:" g end]
      | |- In _ [0; 1; 2] => cbn; clear; lia
      | |- 0 <= _ < _ => cbn; clear; lia
      | |- lenv _ _ _ _ ?l _ => unify l lo; lenv_tac
      | |- lres _ _ _ _ _ => lres_tac
      | |- _ = Z_to_bv 64 _ => reflexivity
      | |- ?g => idtac "LEFT-SSE:" g
      end end
  | ].
Ltac st_norm :=
  lazymatch goal with |- cps _ (ASTA RT ?Sn _ _) _ =>
  lazymatch goal with LVn : rt_live RT Sn = rt_live RT ?Sp |- _ =>
    lazymatch goal with LVp : rt_live RT Sp = _ |- _ => rewrite LVp in LVn end;
    lazymatch goal with FRn : rt_frames RT Sn = rt_frames RT Sp |- _ => lazymatch goal with FRp : rt_frames RT Sp = _ |- _ => rewrite FRp in FRn end end;
    lazymatch goal with SPn : rt_sp0 RT Sn = rt_sp0 RT Sp |- _ => lazymatch goal with SPp : rt_sp0 RT Sp = _ |- _ => rewrite SPp in SPn end end;
    lazymatch goal with CRn : rt_credit RT Sn = rt_credit RT Sp |- _ => lazymatch goal with CRp : rt_credit RT Sp = _ |- _ => rewrite CRp in CRn end end;
    (* [comment removed for export] *)
    repeat match goal with H : context [Sp] |- _ => clear H end; try clear Sp
  end end.
Ltac rows_norm sel :=
  lazymatch goal with H : sel_obj _ _ sel (mkSelv _ _ _ _ _ _ (list_upd2 ?r ?i ?j ?v)) |- _ =>
    let r' := eval cbv in (list_upd2 r i j v) in change (list_upd2 r i j v) with r' in H; rename H into SOBJ end.
(* [comment removed for export] *)
Ltac outside_side ::= cbn [outside sa_arr sa_n sa_strs]; first [ exact I | repeat split;
  lazymatch goal with |- ~ (_ <= ?x < _) =>
    repeat match goal with H : context [x] |- _ => revert H end;
    repeat match goal with H : _ + _ <= _ + -176 |- _ => revert H end;
    clear; intros; lia end ].
(* [comment removed for export] *)
Ltac selstr_gc m0 :=
  repeat match goal with H : wmono asegs ?a _ |- _ => lazymatch a with m0 => fail | _ => clear H end end;
  repeat match goal with A : fs_agree ?a ?b, B : fs_agree ?b ?c |- _ => pose proof (fs_agree_trans a b c A B); clear A B; try clear b end;
  repeat match goal with H : frm0 ?f |- _ => lazymatch goal with |- context [f] => fail | _ => clear H; try clear f end end;
  repeat match goal with x : byte |- _ => clear x end;
  repeat match goal with x : word |- _ => clear x end;
  repeat match goal with x : mem |- _ => clear x end.
(* [comment removed for export] *)
Ltac selstr_iter m0 txt sel lo usp PFS APA off :=
  lazymatch goal with MST : mat_stable _ |- _ =>
  tsel_cells txt off;
  let c := eval cbv in (nth off (TSEL_TEXT 1) 0) in
  lazymatch c with
  | 79 =>
      (* [comment removed for export] *)
      lazymatch goal with SO : sel_obj ?lv ?mm sel _, LVc : rt_live RT ?S = _ |- cps _ (ASTA RT ?S _ _) _ =>
        let KIN := fresh "KIN" in
        assert (KIN : In (sel, 32) (rt_live RT S)) by (rewrite LVc; cbn [In]; do 6 right; left; reflexivity);
        pose proof (proj1 SO) as KC; unfold sel_cells in KC; cbn [s_sy s_sx s_cy s_cx s_data s_rowp s_rows] in KC;
        chunk_facts RT AF GP sel 32; refresh RT AF; unfold shad, SHB in *; park_disj
      end;
      walk_to AF MST [(usp + -176, usp); (sel, sel + 32)] SCS_STOPS;
      try (shbr_beqz1; awalk SCS_STOPS);
      lazymatch goal with |- context [MS ?R _ _ _ _ _ _] =>
        let k11 := eval vm_compute in (bv_key (Z_to_bv 5 11)) in let vy := eval cbv beta iota delta [tget mkR] in (tget k11 R) in
        let k12 := eval vm_compute in (bv_key (Z_to_bv 5 12)) in let vx := eval cbv beta iota delta [tget mkR] in (tget k12 R) in
        lazymatch vy with
        | Some (Z_to_bv 64 ?cy) => lazymatch vx with Some (Z_to_bv 64 ?cx) => sobj_origin sel lo cy cx | Some z64 => sobj_origin sel lo cy 0 end
        | Some z64 => lazymatch vx with Some (Z_to_bv 64 ?cx) => sobj_origin sel lo 0 cx | Some z64 => sobj_origin sel lo 0 0 end end
      end;
      (* [comment removed for export] *)
      cps_stop;
      art_now RT AF ltac:(cbn [ivls_client]; split; [intros zz Hzz; left; ul
                                | split; [intros zz Hzz; right; right; left; exists sel, 32; split; [assumption| clear - Hzz; lia]| exact I]]);
      to_entry;
      lazymatch goal with
      | AGF : agree_on ?PF _ ?mm, MUx : munch _ ?mm _ |- _ => is_var PF;
          agf_munch AGF MUx ltac:(fun Hx => pose proof (PFS _ Hx) as P1; pose proof (proj1 (APA _ Hx)) as P2;
                                         match goal with L : lo + _ <= usp |- _ => clear - P1 P2 L end; cbn [outside]; lia)
      end
  | _ =>
      walk_to AF MST [(usp + -176, usp)] SCS_STOPS;
      sobj_move sel lo;
      (* [comment removed for export] *)
      cps_stop; art_now RT AF ltac:(cbn [ivls_client]; split; [intros zz Hzz; left; ul| exact I]); to_entry;
      lazymatch goal with
      | MUx : munch _ ?ma ?ma |- _ => clear MUx
      | AGF : agree_on ?PF _ ?mm, MUx : munch _ ?mm _ |- _ => is_var PF; agf_munch AGF MUx ltac:(fun Hx => cbn [outside]; pose proof (PFS _ Hx); split; [lia| exact I])
      end
  end;
  (* [comment removed for export] *)
  repeat match goal with H : ro_cells asegs _ _ _ |- _ => clear H end; repeat match goal with H : acc asegs _ _ _ |- _ => clear H end;
  selstr_call sel lo;
  [ repeat match goal with |- context [nth ?n ?l ?d] => let v := eval cbv in (nth n l d) in change (nth n l d) with v end;
    cbn [s_sy s_sx s_cy s_cx s_data s_rowp s_rows];
    after_call RT AF;
    fold_ag ltac:(fun Hx => split; [apply (aclient_mono _ _ usp _ _ _ _ Hx); [first [solve [live_sub_tac] | solve [live_add_tac]] | solve [frames_sub_tac] | lia]
                                   | cbn [outside]; pose proof (APA _ Hx) as (? & ? & ? & ? & ? & ? & ?); lia]);
    st_norm; rows_norm sel;
    refresh RT AF; lib_refresh RT GP; unfold shad, SHB in *; park_disj; selstr_gc m0
  | .. ]
  end.

